<template><view class="page"><view class="card form"><input v-model="actualQuantity" type="digit" placeholder="实际服务数量" /><textarea v-model="completionNote" placeholder="填写完成说明" /><button @click="chooseProofs">选择完成凭证（{{ proofUrls.length }}/9）</button><button class="primary" @click="submit">提交完成</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{submitOrder}from'@/api/player';import{uploadFile}from'@/services/http';const id=ref(0),actualQuantity=ref('1'),completionNote=ref(''),proofUrls=ref<string[]>([]);onLoad(q=>id.value=Number(q?.id));async function chooseProofs(){const picked=await uni.chooseImage({count:9-proofUrls.value.length});uni.showLoading({title:'上传中'});try{for(const path of picked.tempFilePaths)proofUrls.value.push(await uploadFile(path))}finally{uni.hideLoading()}}async function submit(){if(!completionNote.value)return uni.showToast({title:'请填写完成说明',icon:'none'});if(!proofUrls.value.length)return uni.showToast({title:'请至少上传一项凭证',icon:'none'});await submitOrder(id.value,{actualQuantity:Number(actualQuantity.value),completionNote:completionNote.value,proofUrls:proofUrls.value});uni.showToast({title:'提交成功'});setTimeout(()=>uni.navigateBack(),500)}</script>
<style scoped>.form{display:flex;flex-direction:column;gap:24rpx}.form input,.form textarea{background:#f6f7fa;border-radius:16rpx;padding:20rpx}.form textarea{width:100%;height:260rpx;box-sizing:border-box}</style>
